"""Rebuild the frozen identity seed from the saved authoritative published selection.
No network access. Pedagogical grouping is original and separate from source rank.
"""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
groups = {
 'arrays': ('Arrays & Hashing', [1,7,15,24,38], 'Membership, counting, and reusable summaries.', 'Use a set for membership; a dict or Counter for frequencies or value-to-index lookup. Repeated scans often signal a reusable summary. Avoid hashing when ordering or worst-case guarantees matter. Hash operations are expected O(1); total space is usually O(n). Check duplicates, empty inputs, and whether to look up before inserting.', 'Python iteration and indexing', 'seen = set()\nfor value in values:\n    if value in seen:\n        handle_repeat(value)\n    seen.add(value)'),
 'two-pointers': ('Two Pointers', [5,31,49,59,69], 'Maintain an invariant while moving two boundaries.', 'Consider two pointers for sorted pairs, partitioning, or opposite-end constraints. State what is already settled outside the pointers. Move a pointer only when its discarded candidates cannot improve the answer. Sorting may change indices and cost O(n log n). Do not use opposite-end elimination without a monotonic argument. Each pointer moving at most n times yields O(n) work.', 'Arrays; sorting', 'left, right = 0, len(values) - 1\nwhile left < right:\n    if should_move_left(left, right):\n        left += 1\n    else:\n        right -= 1'),
 'sliding-window': ('Sliding Window', [30,62,67], 'Reuse information across contiguous ranges.', 'Fixed windows remove one item and add one; variable windows expand and shrink while maintaining a measurable condition. A frequency dict tracks multiplicity; a set only tracks membership. Use when valid boundaries move monotonically. Arbitrary negative-sum constraints may break that property. Track whether counts mean missing items or distinct requirements. Two moving boundaries give O(n) work when updates are constant time.', 'Arrays & Hashing; Two Pointers', 'left = 0\nfor right, value in enumerate(values):\n    add(value)\n    while invalid():\n        remove(values[left])\n        left += 1\n    record_window(left, right)'),
 'stack': ('Stacks & Monotonic Stacks', [2,13,25,34,72,75], 'Keep unresolved work in last-in, first-out order.', 'Use a stack for nesting, parsing, undo, and unresolved nearest-boundary questions. A monotonic stack removes entries once they can be finalized. Push/pop once gives amortized O(n), even inside a nested loop. A queue instead serves earliest work first. Be precise about equal values, empty pops, operator order, and sentinels.', 'Python lists', 'stack = []\nfor item in items:\n    while stack and can_finalize(stack[-1], item):\n        finalize(stack.pop())\n    stack.append(item)'),
 'binary-search': ('Binary Search', [8,14,42,47], 'Discard half of an ordered search space.', 'Use sorted values or a monotone predicate. Prefer a half-open [lo, hi) boundary template; the unresolved indices are [lo, hi), while the first feasible boundary remains between lo and hi inclusive. When lo equals hi, that boundary is determined. Binary search needs random access and monotonicity, not simply a numeric answer. Each iteration halves the range: O(log n) comparisons, O(1) auxiliary space. Test empty ranges and first/last candidates.', 'Arrays; comparison invariants', 'lo, hi = 0, len(values)\nwhile lo < hi:\n    mid = (lo + hi) // 2\n    if feasible(mid):\n        hi = mid\n    else:\n        lo = mid + 1\n# lo is the first feasible position, or len(values)'),
 'linked-list': ('Linked Lists', [3,12,18,22,65,74], 'Reason about node identity and pointer ownership.', 'Use pointer rewiring when random access is unavailable. A dummy node simplifies changes at the head; slow/fast pointers compare traversal speeds. Save a successor before overwriting next. Do not confuse equal values with identical nodes. Traversal costs O(n); index access is also O(n). Watch cycles, one-node lists, shared nodes, and detached chains.', 'References; loops', 'dummy = Node()\ntail = dummy\nwhile node is not None:\n    successor = node.next\n    tail.next = node\n    tail = node\n    node = successor'),
 'trees': ('Trees & Binary Search Trees', [6,10,11,21,23,32,39,46,55,58,66,68], 'Combine subtree answers or visit one level at a time.', 'DFS uses O(h) stack space and naturally combines children; BFS uses O(width) space and exposes levels. A BST ordering rule applies to entire subtrees, not only immediate children. Define what recursion returns and the empty-subtree answer. Prefer iteration for very deep trees in Python. A full traversal costs O(n). Height can be n in a skewed tree.', 'Stacks; recursion; queues', 'def fold(node):\n    if node is None:\n        return empty_answer\n    left = fold(node.left)\n    right = fold(node.right)\n    return combine(node, left, right)'),
 'graphs': ('Graphs & Grid Traversal', [9,28,33,35,40,41,48,63,71], 'Explore connections, dependencies, and shortest unweighted paths.', 'DFS explores a branch; BFS finds minimum edge count in unweighted graphs. Mark discovered vertices when enqueuing to avoid repeated work. Track all components; directed cycle detection needs active-path state or indegrees. A grid is an implicit graph. Traversals cost O(V+E), or O(rows*cols) for bounded neighbors. Weighted paths need a different algorithm. Check disconnected nodes and mutation permissions.', 'Trees; sets; queues', 'from collections import deque\nseen = {start}\nqueue = deque([start])\nwhile queue:\n    node = queue.popleft()\n    for nxt in neighbors(node):\n        if nxt not in seen:\n            seen.add(nxt)\n            queue.append(nxt)'),
 'heaps': ('Heaps & Priority Queues', [29,70], 'Access the next extreme without fully sorting.', 'Use a heap for incremental selection, top-k maintenance, or merging sorted streams. Python heapq is a min-heap; negate numeric priorities for a max-heap. Push/pop costs O(log k) for heap size k, heapify O(k). A heap is not globally sorted and arbitrary deletion is costly. Include a tie-breaker when payloads cannot be compared.', 'Arrays; ordering', 'import heapq\nheap = []\nfor priority, serial, item in items:\n    heapq.heappush(heap, (priority, serial, item))\npriority, serial, item = heapq.heappop(heap)'),
 'intervals': ('Intervals', [27,45,73], 'Turn overlap questions into ordered boundary decisions.', 'Sort intervals by the boundary required by your proof. Merging uses start order; selecting nonoverlapping work often uses end order. Define whether touching endpoints overlap. Sorting costs O(n log n), then a scan may be linear. Greedy selection fails when arbitrary weights require comparing future profit. Check empty lists and contained intervals.', 'Sorting; binary search for weighted cases', 'for start, end in sorted(intervals):\n    if merged and start <= merged[-1][1]:\n        merged[-1][1] = max(merged[-1][1], end)\n    else:\n        merged.append([start, end])'),
 'backtracking': ('Backtracking & Recursion', [43,44,54,60,61], 'Enumerate choices with reversible local state.', 'Describe state, legal choices, stopping condition, and how to undo a choice. Use when all combinations or paths are requested; exponential work may be inherent. Prune impossible branches without discarding valid solutions. Copy a path when storing it. Distinguish reuse from one-time choices and distinguish path-local from global visited state. Output storage often dominates complexity.', 'Recursion; sets', 'def search(state, path):\n    if complete(state):\n        answers.append(path.copy())\n        return\n    for choice in choices(state):\n        apply(choice)\n        path.append(choice)\n        search(next_state(state, choice), path)\n        path.pop()\n        undo(choice)'),
 'dp': ('Dynamic Programming', [16,26,37,50,51,56,57], 'Cache the answers to overlapping subproblems.', 'Define a state in one sentence, then list choices and base cases. A transition must depend on smaller or already-computed states. Memoization explores reachable states; tabulation gives control over order and memory. Complexity is number of states times work per state, plus output. Avoid DP when no subproblems repeat. Test unreachable states and empty prefixes; loop direction controls reuse.', 'Recursion; arrays', 'dp = [unreachable] * (size + 1)\ndp[0] = base_case\nfor state in range(1, size + 1):\n    for previous in predecessors(state):\n        dp[state] = combine(dp[state], dp[previous])'),
 'tries': ('Tries', [36], 'Share prefixes across many string lookups.', 'A trie stores one edge per symbol; terminal markers distinguish complete words from prefixes. Insert/search cost O(L) for word length L. It is useful for prefix queries, while a hash set is often simpler for full-word membership. Memory can be large with per-node dictionaries. Test a word that is also another word\'s prefix.', 'Dictionaries; trees', 'node = root\nfor char in word:\n    node = node.children.setdefault(char, TrieNode())\nnode.terminal = True'),
 'strings': ('Strings & Simulation', [20,52,53], 'Translate a precise specification into a small state machine.', 'Track the minimal state required to process the next character or boundary. Separate whitespace, sign, digits, carry, and stopping rules when relevant. Python strings are immutable: repeated prepending can become quadratic; collect characters and join once. Matrix simulation needs explicit boundary invariants. Check empty input, overflow rules, and final carry.', 'Loops; indexing', 'output = []\nstate = initial_state\nfor token in tokens:\n    state, emitted = step(state, token)\n    output.extend(emitted)\nanswer = "".join(output)'),
 'greedy': ('Greedy & Counting Invariants', [4,17,19,64], 'Prove why a local choice preserves a global answer.', 'A greedy step needs an exchange or cancellation argument. Counting often identifies a bottleneck or an unavoidable lower bound. Do not use greedy just because a local choice looks good; weighted constraints may require DP. Describe what remains possible after each choice. Confirm assumptions such as an existing majority or a fixed alphabet.', 'Arrays & Hashing; sorting', 'state = initial_summary\nfor value in values:\n    state = update_invariant(state, value)\n# Verify any candidate if the problem does not guarantee existence.')
}
published=json.loads((ROOT/'data/sources/QuestionGroups.json').read_text())
rows=[{k:p[k] for k in ('url','title','difficulty')} for week in published.values() for p in week]
assert rows==json.loads((ROOT/'data/sources/published75.json').read_text()), 'Published JSON and saved rendered page disagree'
# Breadth across basic patterns first, then deeper questions within each concept.
early=[1,7,15,24,5,8,2,3,18,12,22,6,23,9,17,19,20,14,13,25,30,31,32,11,21,10,33,40,28,41,35]
rest=[r for group in groups.values() for r in group[1] if r not in early]
order=early+rest
assert len(order)==len(set(order))==75
concepts=[]
for idx,(cid,(name,ranks,description,body,prereq,template)) in enumerate(groups.items()):
 concepts.append(dict(id=cid,name=name,display_order=idx,description=description,body=body,prerequisites=prereq,template=template))
seed=[]
for rank,row in enumerate(rows,1):
 cid=next(k for k,v in groups.items() if rank in v[1]);slug=row['url'].rstrip('/').split('/')[-1]
 secondary={'linked-list':['heaps'] if rank==74 else ['arrays'] if rank==65 else [],'graphs':['arrays'],'dp':['arrays'],'sliding-window':['arrays','two-pointers'],'intervals':['binary-search'] if rank==73 else []}.get(cid,[])
 seed.append(dict(id=slug,leetcode_slug=slug,**row,grind_rank=rank,learning_order=order.index(rank)+1,primary_concept_id=cid,secondary_patterns=secondary,premium_status='free',source_version='published75-2026-10-15-v1'))
for name,obj in [('concepts',concepts),('grind75',seed)]:
 (ROOT/f'data/{name}.json').write_text(json.dumps(obj,indent=2)+'\n')
